  function reasonText(reasons){return (reasons||[]).map(function(reason){return RECOVERY_REASON[reason]||String(reason).replace(/_/g,' ');}).join('; ');}
  function recoveryInfo(scope,monitoring,monitoringError){
    if(!monitoring)return {status:monitoringError?'Belum dapat dicek':'Belum dibandingkan',reason:monitoringError?'Perbandingan sensor sedang tidak dapat dimuat, jadi status recovery belum diketahui. Estimasi RINTIK di atas tetap valid.':'Tanggal ini belum dibandingkan dengan sensor humidity.',action:false};
    var recovery=monitoring.recovery||{status:'inactive',values:[]},explanation=recovery.explanation||null,code=explanation&&explanation.code,incident=monitoring.incident,gate=monitoring.recovery_gate;
    var sensorState=sensorStateOf(monitoring)||monitoring.sensor_state,sensorMissing=sensorState==='missing_simulated',faulty=sensorState==='stuck_simulated'||sensorState==='deviating_simulated';
    var problem=sensorMissing?'Sensor tidak mengirim data.':sensorState==='stuck_simulated'?'Sensor masih mengirim data, tetapi nilainya macet (hampir konstan) sehingga dicurigai rusak.':'Sensor masih mengirim data, tetapi nilainya menyimpang jauh dari estimasi sehingga dicurigai rusak.';
    var raw=sensorMissing?'Data sensor mentah tetap kosong, tidak ditimpa.':'Bacaan sensor mentah tetap disimpan apa adanya, tidak ditimpa.';
    if(recovery.status==='active_estimated'||code==='recovery_active_estimated')return {status:'Aktif · estimated',reason:(scope==='operational'?'Skenario "Hilang" pada simulasi 2026: estimasi RINTIK dipakai sebagai nilai pengganti berlabel estimated. ':'Insiden sensor sudah dikonfirmasi (teknisi simulasi) dan syarat demo terpenuhi, jadi estimasi RINTIK dipakai sebagai pengganti berlabel estimated. ')+raw,action:false};
    if(scope==='operational'&&faulty)return {status:'Tidak diperagakan',reason:problem+' Di Operasional Harian, nilai pengganti hanya diperagakan untuk skenario "Hilang". Untuk alur konfirmasi teknisi, gunakan Demo Resmi 4–6 September.',action:false};
    if(code==='no_sensor_incident'||(!incident&&!code&&!sensorMissing))return {status:'Tidak diperlukan',reason:'Sensor humidity mengirim data yang wajar pada tanggal ini, jadi tidak ada nilai pengganti.',action:false};
    /* R2: safety gate first. A failed/expired audit or an unhealthy pipeline blocks recovery; the confirm button never overrides it. */
    var blocking=reasonText((explanation&&explanation.blocking_reasons)||(gate&&gate.reasons));
    if(recovery.status==='historical_estimate_restricted'||code==='blocked_by_accuracy_audit'||code==='blocked_by_operational_health')return {status:'Dibatasi',reason:problem+' Nilai pengganti ditahan oleh gate keamanan'+(blocking?': '+blocking:'')+'. Ubah skenario audit demo di Pengaturan bila ingin melanjutkan.',action:false};
    var canConfirm=scope==='official'&&incident&&(code?code==='awaiting_incident_confirmation'||(explanation.next_steps||[]).indexOf('confirm_incident_with_demo_override')>=0:incident.status!=='confirmed_simulation');
    if(canConfirm)return {status:'Menunggu konfirmasi',reason:problem+' Estimasi RINTIK sudah tersedia, tetapi belum dipakai sebagai pengganti: insiden harus dikonfirmasi dulu oleh teknisi (di demo ini disimulasikan dengan satu klik). Estimasi bukan izin otomatis untuk mengganti sensor.',action:true};
    return {status:'Tidak aktif',reason:blocking?'Recovery belum diizinkan: '+blocking+'.':'Belum ada nilai pengganti untuk tanggal ini.',action:false};
  }
